import React from 'react';
import { Link } from 'react-router-dom';
import { getFpcTab, type FpcDemoTabKey } from './fpcTabRegistry';
import styles from './FpcPlaceholderPage.module.css';

export interface FpcPlaceholderPageProps {
  tabKey: FpcDemoTabKey;
}

/**
 * Placeholder theo tab demo/fpc — mount trên route thật.
 * Không chứa logic nghiệp vụ; thay bằng page thật qua `/implement-kpi`.
 */
const FpcPlaceholderPage: React.FC<FpcPlaceholderPageProps> = ({ tabKey }) => {
  const tab = getFpcTab(tabKey);
  const testId = `fpc-placeholder-${tab.key}`;

  return (
    <div className={styles.page} data-testid={`${testId}-page`} data-lin-page-id={tab.implementFeature}>
      <header className={styles.header}>
        <div className={styles.titleBlock}>
          <div className={styles.titleRow}>
            <i className={`${tab.iconClass} ${styles.titleIcon}`} aria-hidden />
            <h1 className={styles.title}>{tab.labelVi}</h1>
          </div>
          <p className={styles.subtitle}>
            Placeholder — clone UI từ demo tab «{tab.labelVi}» khi chạy{' '}
            <code>/implement-kpi --feature {tab.implementFeature}</code>
          </p>
        </div>
        <div className={styles.badges}>
          <span className={`${styles.badge} ${styles.badgePhase}`}>{tab.phase}</span>
          <span className={`${styles.badge} ${styles.badgeStatus}`}>Chưa implement</span>
        </div>
      </header>

      <section className={styles.card} data-testid={`${testId}-card`}>
        <h2 className={styles.cardTitle}>Sẵn sàng cho /implement-kpi</h2>
        <p className={styles.cardBody}>
          Form/report cũ đã được gỡ. Trang này giữ route + menu theo demo/fpc. Khi implement: xác nhận{' '}
          <code>demo_form_ref</code> → clone demo (cấm sửa demo) → chuẩn hóa ERP form.
        </p>
        <ul className={styles.metaList}>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Route</span>
            <span className={styles.metaValue}>{tab.route}</span>
          </li>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Demo SSOT</span>
            <span className={styles.metaValue}>/demo/fpc · tab={tab.demoTabKey}</span>
          </li>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Feature alias</span>
            <span className={styles.metaValue}>{tab.implementFeature}</span>
          </li>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Context</span>
            <span className={styles.metaValue}>{tab.contextDoc}</span>
          </li>
        </ul>
        <div className={styles.actions}>
          <Link
            className={`${styles.linkBtn} ${styles.linkBtnPrimary}`}
            to="/demo/fpc"
            data-testid={`${testId}-open-demo`}
          >
            <i className="fas fa-desktop" aria-hidden /> Xem demo/fpc
          </Link>
        </div>
      </section>
    </div>
  );
};

export default FpcPlaceholderPage;
